import java.util.*;
public class Main {
    enum Scenario { OK, CREATED, NO_CONTENT, BAD_REQUEST, UNAUTHORIZED, FORBIDDEN, NOT_FOUND, METHOD_NOT_ALLOWED, CONFLICT, UNPROCESSABLE, SERVER_ERROR }
    static int code(Scenario s){
        switch(s){
            case OK: return 200;
            case CREATED: return 201;
            case NO_CONTENT: return 204;
            case BAD_REQUEST: return 400;
            case UNAUTHORIZED: return 401;
            case FORBIDDEN: return 403;
            case NOT_FOUND: return 404;
            case METHOD_NOT_ALLOWED: return 405;
            case CONFLICT: return 409;
            case UNPROCESSABLE: return 422;
            case SERVER_ERROR: return 500;
        }
        return 500;
    }
    public static void main(String[] a){
        Scenario[] ss={Scenario.CREATED,Scenario.NO_CONTENT,Scenario.UNAUTHORIZED,Scenario.METHOD_NOT_ALLOWED,Scenario.CONFLICT,Scenario.UNPROCESSABLE,Scenario.SERVER_ERROR};
        for(Scenario s:ss) System.out.println(s+" -> "+code(s));
    }
}
